import{_ as r,C as o,o as i,c as n,j as t,a as s,E as l,al as d}from"./chunks/framework.7vp1BMOE.js";const c="/px4_user_guide/assets/agam_v6xrt_front.CSHWoIry.png",w=JSON.parse('{"title":"Agam Autopilot v6X-RT","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_controller/agam_v6xrt.md","filePath":"en/flight_controller/agam_v6xrt.md"}'),h={name:"en/flight_controller/agam_v6xrt.md"};function p(u,e,m,g,b,f){const a=o("Badge");return i(),n("div",null,[e[0]||(e[0]=t("h1",{id:"agam-autopilot-v6x-rt",tabindex:"-1"},[s("Agam Autopilot v6X-RT "),t("a",{class:"header-anchor",href:"#agam-autopilot-v6x-rt","aria-label":'Permalink to "Agam Autopilot v6X-RT"'},"​")],-1)),l(a,{type:"tip",text:"main (PX4 v2.0)"}),e[1]||(e[1]=d('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://www.agamrobotics.com/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <a href="https://www.agamrobotics.com/product-page/agam-pixhawk-6x-full-set" target="_blank" rel="noreferrer">Agam Autopilot v6X-RT</a> flight controller is <a href="https://www.agamrobotics.com/" target="_blank" rel="noreferrer">Agam Robotics&#39;</a> implementation of the <a href="./../flight_controller/nxp_mr_vmu_rt1176">NXP-led FMUv6X-RT reference design</a>.</p><p><img src="'+c+'" alt="Agam Autopilot v6X-RT"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Agam Autopilot v6X-RT uses the NXP i.MX RT1176 MCU, consisting of an Arm® Cortex®-M7 core at 1GHz and an Arm® Cortex®-M4 core at 400MHz, with 2MB SRAM and 64MB Octal SPI flash. The increased processing power lets firmware developers run more complex algorithms without being constrained by the flight controller&#39;s compute budget.</p><p>The board uses sensors from InvenSense® and Bosch®, and ships in two sensor-set variants (see <a href="#processors-sensors">Processors &amp; Sensors</a>). Redundant IMU and barometer sensors sit on separate buses, and 2 of the 3 IMUs are mounted on a shock-isolated, heated sensor board, separate from the FMU board itself, to improve accuracy in flight and across a wide temperature range.</p><p>An integrated Ethernet interface (100BASE-T1, 2-wire) provides high-speed, low-latency connectivity to companion computers (for example a Raspberry Pi or NVIDIA Jetson), cameras, or data-transmission systems.</p><h2 id="key-design-points" tabindex="-1">Key Design Points <a class="header-anchor" href="#key-design-points" aria-label="Permalink to &quot;Key Design Points&quot;">​</a></h2><ul><li>High-performance <a href="https://www.nxp.com/products/i.MX-RT1170" target="_blank" rel="noreferrer">NXP i.MX RT1176</a> dual-core MCU</li><li><a href="https://www.nxp.com/products/SE051" target="_blank" rel="noreferrer">NXP EdgeLock SE051</a> hardware secure element, field-updatable, certified to CC EAL 6+</li><li>Triple redundant IMU (2 sensors on a shock-mounted, heated sensor board, 1 on the FMU board itself) and dual redundant barometer, each on a separate bus</li><li>Independent power control and separate buses for each sensor domain</li><li>100BASE-T1 (2-wire) automotive Ethernet for high-speed companion computer integration</li><li>256Kbit FRAM</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This board ships with <code>SENS_IMU_MODE</code> and <code>EKF2_MULTI_IMU</code> set so that only the FMU-board IMU is used by default. To take advantage of the triple-redundant IMU set <code>SENS_IMU_MODE</code> to <code>Disabled (0)</code>, reboot, set <code>EKF2_MULTI_IMU</code> to <code>3</code>, and reboot again. See <a href="https://agamrobotics.gitbook.io/docs/autopilots-flight-controller/quickstart/imu-triple-redundancy-feature" target="_blank" rel="noreferrer">Agam&#39;s IMU triple redundancy notes</a> for more information.</p></div><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors {#processors-sensors}&quot;">​</a></h3><ul><li>FMU Processor: <a href="https://www.nxp.com/products/i.MX-RT1170" target="_blank" rel="noreferrer">NXP i.MX RT1176 (MIMXRT1176DVMAA)</a><ul><li>Arm® Cortex®-M7 core @ 1GHz</li><li>Arm® Cortex®-M4 core @ 400MHz (secondary core)</li><li>2MB SRAM</li><li>64MB external Octal SPI flash</li></ul></li><li>On-board sensors — Agam Autopilot v6X-RT ships in two sensor-set variants (Sensor Set 1 and Sensor Set 3, per <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-020%20Pixhawk%20Autopilot%20v6X-RT%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Standards</a>): <ul><li>Sensor Set 1: <ul><li>2x <a href="https://www.invensense.tdk.com/products/motion-tracking/6-axis/icm-42688-p/" target="_blank" rel="noreferrer">InvenSense ICM-42688-P IMU</a></li><li><a href="https://www.bosch-sensortec.com/products/motion-sensors/imus/bmi088/" target="_blank" rel="noreferrer">Bosch BMI088 IMU</a></li><li><a href="https://www.bosch-sensortec.com/media/boschsensortec/downloads/datasheets/bst-bmm150-ds001.pdf" target="_blank" rel="noreferrer">Bosch BMM150 Magnetometer</a></li><li>2x <a href="https://www.bosch-sensortec.com/en/products/environmental-sensors/pressure-sensors/bmp390/" target="_blank" rel="noreferrer">Bosch BMP388 Barometer</a></li></ul></li><li>Sensor Set 3: <ul><li>2x <a href="https://www.invensense.tdk.com/en-us/products/6-axis/icm-45686" target="_blank" rel="noreferrer">TDK InvenSense ICM-45686 IMU</a></li><li><a href="https://www.bosch-sensortec.com/products/motion-sensors/imus/bmi088/" target="_blank" rel="noreferrer">Bosch BMI088 IMU</a></li><li><a href="https://www.bosch-sensortec.com/en/products/motion-sensors/magnetometers/bmm350" target="_blank" rel="noreferrer">Bosch BMM350 Magnetometer</a></li><li>2x <a href="https://www.bosch-sensortec.com/en/products/environmental-sensors/pressure-sensors/bmp390/" target="_blank" rel="noreferrer">Bosch BMP388 Barometer</a></li></ul></li></ul></li></ul><h3 id="electrical-data" tabindex="-1">Electrical data <a class="header-anchor" href="#electrical-data" aria-label="Permalink to &quot;Electrical data&quot;">​</a></h3><ul><li>Voltage Ratings: <ul><li>Max input voltage: 6V</li><li>USB Power Input: 4.75~5.25V</li><li>Servo Rail Input: 0~36V</li></ul></li><li>Current Ratings: <ul><li><code>TELEM1</code> output current limiter: 1.5A</li><li>All other port combined output current limiter: 1.5A</li></ul></li></ul><h3 id="mechanical-data" tabindex="-1">Mechanical data <a class="header-anchor" href="#mechanical-data" aria-label="Permalink to &quot;Mechanical data&quot;">​</a></h3><ul><li>Dimensions <ul><li>Flight controller module: 39 x 32 x 16 mm</li><li>Baseboard: 95 x 50 x 19 mm</li></ul></li><li>Weight: 90 g</li><li>Operating temperature: -40°C to 85°C</li></ul><h3 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h3><ul><li>12 PWM/DShot outputs (8 DShot-capable, 4 PWM-only)</li><li>1x RC input, SBUS/PPM</li><li>1x dedicated DSM/Spektrum RC input</li><li>3x TELEM ports (<code>TELEM1</code>, <code>TELEM2</code>, <code>TELEM3</code>), full flow control</li><li>2x GPS ports (<code>GPS1</code> full GPS plus safety switch and buzzer, <code>GPS2</code> basic)</li><li>4x I2C</li><li>3x CAN-FD</li><li>1x SPI bus, 2 chip-select lines, 2 data-ready lines, 1 sync line, 1 reset line</li><li>1x NFC antenna port (connected to the SE051 secure element)</li><li>100BASE-T1 Ethernet (single 2-wire port)</li><li>USB 2.0</li><li>microSD card slot</li><li>Dual redundant power input (5V via Molex connectors)</li></ul><h2 id="store" tabindex="-1">Where To Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where To Buy {#store}&quot;">​</a></h2><p>Order from the <a href="https://www.agamrobotics.com/product-page/agam-pixhawk-6x-full-set" target="_blank" rel="noreferrer">Agam Robotics store</a>.</p><h2 id="assembly-setup" tabindex="-1">Assembly/Setup <a class="header-anchor" href="#assembly-setup" aria-label="Permalink to &quot;Assembly/Setup&quot;">​</a></h2><p>Agam Autopilot v6X-RT is a Pixhawk-standard v6X-RT board, electrically and mechanically identical to the NXP reference design, differing from it only in enclosure. Wiring is similar to the <a href="./../flight_controller/pixhawk6x#connections">Holybro Pixhawk 6X</a> and other boards that follow the <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-009%20Pixhawk%20Connector%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Connector Standard</a>.</p><p>For wiring and assembly, follow the <a href="./../assembly/quick_start_pixhawk6x">Pixhawk 6X Wiring Quick Start</a>, which applies to this board other than the enclosure.</p><h2 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;Connections&quot;">​</a></h2><p>The connectors follow the <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-009%20Pixhawk%20Connector%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Connector Standard</a>, which defines the pinout of each port type. For the physical layout of the ports on the board see the <a href="https://agamrobotics.gitbook.io/docs/autopilots-flight-controller/quickstart/baseboard-port" target="_blank" rel="noreferrer">Agam Autopilot v6X-RT baseboard ports</a> documentation.</p><h2 id="pinouts" tabindex="-1">Pinouts <a class="header-anchor" href="#pinouts" aria-label="Permalink to &quot;Pinouts&quot;">​</a></h2><p>Agam Autopilot v6X-RT&#39;s pinout is the same as other v6X-RT-family boards:</p><ul><li><a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-012%20Pixhawk%20Autopilot%20v6X%20Standard.pdf" target="_blank" rel="noreferrer">DS-012 Pixhawk Autopilot v6X Standard</a></li><li><a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-010%20Pixhawk%20Autopilot%20Bus%20Standard.pdf" target="_blank" rel="noreferrer">DS-010 Pixhawk Autopilot Bus Standard</a></li><li><a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-009%20Pixhawk%20Connector%20Standard.pdf" target="_blank" rel="noreferrer">DS-009 Pixhawk Connector Standard</a></li><li><a href="https://agamrobotics.gitbook.io/docs/autopilots-flight-controller/quickstart/baseboard-port" target="_blank" rel="noreferrer">Agam Autopilot v6X-RT Baseboard Port pinouts</a> (agamrobotics.gitbook.io)</li></ul><p>Notes:</p><ul><li>The <a href="./../camera/fc_connected_camera#camera-capture-configuration">camera capture pin</a> (<code>PI0</code>) is pin 2 on the AD&amp;IO port, marked <code>FMU_CAP</code>.</li></ul><h2 id="serial-port-mapping" tabindex="-1">Serial Port Mapping <a class="header-anchor" href="#serial-port-mapping" aria-label="Permalink to &quot;Serial Port Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Device</th><th>Port</th></tr></thead><tbody><tr><td>LPUART1</td><td>/dev/ttyS0</td><td>Console</td></tr><tr><td>LPUART3</td><td>/dev/ttyS1</td><td>GPS</td></tr><tr><td>LPUART4</td><td>/dev/ttyS2</td><td>TELEM1</td></tr><tr><td>LPUART5</td><td>/dev/ttyS3</td><td>GPS2</td></tr><tr><td>LPUART6</td><td>/dev/ttyS4</td><td>PX4IO</td></tr><tr><td>LPUART8</td><td>/dev/ttyS5</td><td>TELEM2</td></tr><tr><td>LPUART10</td><td>/dev/ttyS6</td><td>TELEM3</td></tr><tr><td>LPUART11</td><td>/dev/ttyS7</td><td>EXT2</td></tr></tbody></table><h2 id="radio_control" tabindex="-1">Radio Control <a class="header-anchor" href="#radio_control" aria-label="Permalink to &quot;Radio Control {#radio_control}&quot;">​</a></h2><p>A remote control (RC) radio system is required if you want to <em>manually</em> control your vehicle (PX4 does not require a radio system for autonomous flight modes). You will need to <a href="./../getting_started/rc_transmitter_receiver">select a compatible transmitter/receiver</a> and then <em>bind</em> them so that they communicate (read the instructions that come with your specific transmitter/receiver).</p><p>The ports and supported protocols are:</p><ul><li><code>RC IN</code> (FMU): SBUS/PPM</li><li><code>DSM RC</code> (FMU): Spektrum/DSM</li></ul><p>For PPM and S.Bus receivers, a single signal wire carries all channels. If your receiver outputs individual PWM signals (one wire per channel) it must be connected via a <a href="./../getting_started/rc_transmitter_receiver">PPM encoder</a>.</p><h2 id="voltage-ratings" tabindex="-1">Voltage Ratings <a class="header-anchor" href="#voltage-ratings" aria-label="Permalink to &quot;Voltage Ratings&quot;">​</a></h2><p><em>Agam Autopilot v6X-RT</em> can be triple-redundant on the power supply if three power sources are supplied. The three power rails are: <strong>POWER1</strong>, <strong>POWER2</strong> and <strong>USB</strong>. The <strong>POWER1</strong> &amp; <strong>POWER2</strong> ports use a 6-circuit <a href="https://www.molex.com/en-us/products/part-detail/5024430670" target="_blank" rel="noreferrer">2.00mm Pitch CLIK-Mate Wire-to-Board PCB Receptacle</a>.</p><h3 id="normal-operation-maximum-ratings" tabindex="-1">Normal Operation Maximum Ratings <a class="header-anchor" href="#normal-operation-maximum-ratings" aria-label="Permalink to &quot;Normal Operation Maximum Ratings&quot;">​</a></h3><p>Under these conditions all power sources will be used in this order to power the system:</p><ol><li><strong>POWER1</strong> and <strong>POWER2</strong> inputs (4.9V to 5.5V)</li><li><strong>USB</strong> input (4.75V to 5.25V)</li></ol><h3 id="absolute-maximum-ratings" tabindex="-1">Absolute Maximum Ratings <a class="header-anchor" href="#absolute-maximum-ratings" aria-label="Permalink to &quot;Absolute Maximum Ratings&quot;">​</a></h3><p>Under these conditions the system will not draw any power (will not be operational), but will remain intact.</p><ol><li><strong>POWER1</strong> and <strong>POWER2</strong> inputs (operational range 4.1V to 5.7V, 0V to 10V undamaged)</li><li><strong>USB</strong> input (operational range 4.1V to 5.7V, 0V to 6V undamaged)</li><li>Servo input: VDD_SERVO pin of <strong>FMU PWM OUT</strong> (0V to 42V undamaged)</li></ol><p>Digital I2C battery monitoring is enabled by default. Analog/ADC battery monitoring is also supported.</p><h2 id="building-firmware" tabindex="-1">Building Firmware <a class="header-anchor" href="#building-firmware" aria-label="Permalink to &quot;Building Firmware&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware from PX4 v2.0. It will be pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agam_fmu-v6xrt_default</span></span></code></pre></div><h2 id="debug_port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug_port" aria-label="Permalink to &quot;Debug Port {#debug_port}&quot;">​</a></h2><p>The <a href="./../debug/system_console">PX4 System Console</a> and <a href="./../debug/swd_debug">SWD interface</a> run on the <strong>FMU Debug</strong> port.</p><p>The pinout and connector comply with the <a href="./../debug/swd_debug#pixhawk-debug-full">Pixhawk Debug Full</a> interface defined in the <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-009%20Pixhawk%20Connector%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Connector Standard</a> (JST SH 1mm pitch, 10-pin connector). Pin 6 is <code>SPI6_MOSI_EXTERNAL1</code>, which is the pad&#39;s <code>JTAG_TDO</code> function and carries <code>SWO</code> when the debug port is in serial-wire mode.</p><table tabindex="0"><thead><tr><th>Pin</th><th>Signal</th><th>Volt</th></tr></thead><tbody><tr><td>1 (red)</td><td><code>FMU_VDD_3V3</code></td><td>+3.3V</td></tr><tr><td>2 (black)</td><td><code>FMU_USART_TX</code></td><td>+3.3V</td></tr><tr><td>3 (black)</td><td><code>FMU_USART_RX</code></td><td>+3.3V</td></tr><tr><td>4 (black)</td><td><code>FMU_SWD_IO</code></td><td>+3.3V</td></tr><tr><td>5 (black)</td><td><code>FMU_SWD_CK</code></td><td>+3.3V</td></tr><tr><td>6 (black)</td><td><code>SWO</code></td><td>+3.3V</td></tr><tr><td>7 (black)</td><td>NFC GPIO</td><td>+3.3V</td></tr><tr><td>8 (black)</td><td>PH11</td><td>+3.3V</td></tr><tr><td>9 (black)</td><td><code>FMU_nRST</code></td><td>+3.3V</td></tr><tr><td>10 (black)</td><td><code>GND</code></td><td>GND</td></tr></tbody></table><p>For information about using this port see:</p><ul><li><a href="./../debug/swd_debug">SWD Debug Port</a></li><li><a href="./../debug/system_console">PX4 System Console</a></li></ul><h2 id="peripherals" tabindex="-1">Peripherals <a class="header-anchor" href="#peripherals" aria-label="Permalink to &quot;Peripherals&quot;">​</a></h2><ul><li><a href="https://agamrobotics.gitbook.io/docs/gnss-and-rtk-systems/agam-gnss01-can" target="_blank" rel="noreferrer">Agam GNSS01 CAN</a></li><li><a href="https://agamrobotics.gitbook.io/docs/gnss-and-rtk-systems/agam-gnss02-can-rtk" target="_blank" rel="noreferrer">Agam GNSS02 CAN RTK</a></li><li><a href="https://agamrobotics.gitbook.io/docs/gnss-and-rtk-systems/agam-gnss-base-rtk" target="_blank" rel="noreferrer">Agam GNSS Base RTK</a></li><li><a href="https://agamrobotics.gitbook.io/docs/sensors/agam-florange-sensor" target="_blank" rel="noreferrer">Agam FloRange Sensor</a></li><li><a href="./../sensor/rangefinders">Rangefinders/Distance sensors</a></li><li><a href="https://holybro.com/collections/telemetry-radios?orderby=date" target="_blank" rel="noreferrer">Telemetry Radio Modules</a></li></ul><h2 id="further-info" tabindex="-1">Further info <a class="header-anchor" href="#further-info" aria-label="Permalink to &quot;Further info&quot;">​</a></h2><ul><li><a href="./../advanced_config/bootloader_update_v6xrt">Update Pixhawk 6X-RT Bootloader</a></li><li><a href="https://agamrobotics.gitbook.io/docs/autopilots-flight-controller/quickstart" target="_blank" rel="noreferrer">Agam Autopilot v6X-RT Documentation</a> (Agam Robotics Docs)</li><li><a href="https://www.youtube.com/playlist?list=PLv71BKC3TLci9fgwV4U6_2C2Uxtrm3SQE" target="_blank" rel="noreferrer">Agam Autopilot v6X-RT setup video playlist</a> (YouTube, Agam Robotics)</li><li><a href="./../assembly/quick_start_pixhawk6x">Pixhawk 6X Wiring QuickStart</a></li><li><a href="https://agamrobotics.gitbook.io/docs/digital-power-modules-dpm/dpm01-6s" target="_blank" rel="noreferrer">Agam Digital Power Module (DPM01)</a></li><li><a href="https://agamrobotics.gitbook.io/docs/analog-power-modules-apm/generic" target="_blank" rel="noreferrer">Agam Analog Power Module (APM)</a></li><li><a href="https://dronecode.org/announcing-the-pixhawk-fmuv6x-rt/" target="_blank" rel="noreferrer">Announcing the Pixhawk FMUv6X-RT</a> (Dronecode Foundation)</li><li><a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-020%20Pixhawk%20Autopilot%20v6X-RT%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk FMUv6X-RT open standard</a></li><li><a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-010%20Pixhawk%20Autopilot%20Bus%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Autopilot Bus Standard</a></li><li><a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-009%20Pixhawk%20Connector%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Connector Standard</a></li></ul>',61))])}const P=r(h,[["render",p]]);export{w as __pageData,P as default};
